-__global__ void sum(const float*x,float*y,int n){using BR=cub::BlockReduce<float,256>;__shared__ typename BR::TempStorage temp;float s=0;for(size_t i=blockIdx.x*blockDim.x+threadIdx.x;i<n;i+=size_t(blockDim.x)*gridDim.x)s+=x[i];float total=BR(temp).Sum(s);if(threadIdx.x==0)atomicAdd(y,total);}
